-- ViaHimalaya trek routes columns
--
-- Pointers to the per-trek routes file generated by scripts/build_routes.py:
-- every way through the trek's network cut into sections (nodes, sections with
-- their own elevation profiles, the default route as section ids, and where each
-- POI sits on them). HANDOFF section 53 item 4.
--
-- Same pattern as poi_url / poi_updated_at (002): the R2 key never changes, so
-- the app compares routes_updated_at with its cached copy to know when to
-- re-download.
--
-- Additive only. Both columns are null until a routes file is uploaded, and the
-- old columns (coordinate_url, elevation_profile, distance, elevation) stay as
-- they are for app versions that do not read routes.

ALTER TABLE treks ADD COLUMN IF NOT EXISTS routes_url VARCHAR(500);
ALTER TABLE treks ADD COLUMN IF NOT EXISTS routes_updated_at TIMESTAMP WITH TIME ZONE;

COMMENT ON COLUMN treks.routes_url IS
    'URL of the routes file on R2, e.g. https://assets.viahimalaya.com/trek_routes/<id>.json. Null when the trek has no routes file.';
COMMENT ON COLUMN treks.routes_updated_at IS
    'When the routes file was last regenerated. The app re-downloads when this changes - the R2 key never does.';
